class DmsApi(KonApi):
    """kon-dms

    Sistema de gestión documental con versionado semántico, workflows de aprobación y trazabilidad completa
    """

    kon = "kon-dms"

    def abrir_documento_por_codigo(self, *, code: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[AbrirDocumentoPorCodigoResult]:
        """Open a document by code

        307 redirect to the reader view (/api/dms/render/<slug>) of the document with this code, if the caller can read it; 404 otherwise.

        REST: `GET /api/dms/render/code/{code}` · scope `kon:dms:abrir-documento-por-codigo`
        idempotent (safe to retry)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            code: Document code
        """
        return self._call(OPERATIONS["abrir-documento-por-codigo"], {"code": code}, None, request_options)

    def archivar_documento(self, *, id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[ArchivarDocumentoResult]:
        """Archive a document

        Archives a document (soft delete: inactive and `archived`; nothing is erased). Owner or admin. 404 when the caller cannot read it, 403 when it may read but is not the owner.

        REST: `DELETE /api/dms/documents/{id}` · scope `kon:dms:archivar-documento`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `dms__archivar-documento`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            id: Document id (uuid; anything else is a 404)
        """
        return self._call(OPERATIONS["archivar-documento"], {"id": id}, None, request_options)

    def borrar_comentario(self, *, comment_id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[BorrarComentarioResult]:
        """Delete a comment

        Deletes a comment: its author, or whoever edits the document (moderation). 404 when the caller cannot see it.

        REST: `DELETE /api/dms/comments/{commentId}` · scope `kon:dms:borrar-comentario`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `dms__borrar-comentario`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            comment_id: Comment id (uuid; anything else is a 404)
        """
        return self._call(OPERATIONS["borrar-comentario"], {"commentId": comment_id}, None, request_options)

    def borrar_diagrama(self, *, diagram_id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[BorrarDiagramaResult]:
        """Delete a diagram

        Deletes a diagram of an editable version (owner or author; 409 when the version is no longer a draft).

        REST: `DELETE /api/dms/diagrams/{diagramId}` · scope `kon:dms:borrar-diagrama`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `dms__borrar-diagrama`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            diagram_id: Diagram id (uuid; anything else is a 404)
        """
        return self._call(OPERATIONS["borrar-diagrama"], {"diagramId": diagram_id}, None, request_options)

